// Package clierr maps the module's sentinel errors to stable CLI error codes
// and exit statuses, so scripts can branch on a code instead of parsing
// prose. The API uses the code vocabulary from CLAUDE.md §5.11
// (not_found, bad_request, rate_limited, internal); the CLI adds codes for
// conditions the API never returns, such as retention_gap.
//
// The catalog is also the source of docs/errors.md, generated by
// scripts/errorcatalog. A test fails when an exported Err* sentinel is added
// without an entry, so the two cannot drift.
package clierr

import (
	"errors"
	"fmt"
	"strings"

	"github.com/Soroban-CII/soroindex/internal/claims"
	"github.com/Soroban-CII/soroindex/internal/config"
	"github.com/Soroban-CII/soroindex/internal/ingest"
	"github.com/Soroban-CII/soroindex/internal/match"
	"github.com/Soroban-CII/soroindex/internal/rpc"
	"github.com/Soroban-CII/soroindex/internal/store"
	indexsync "github.com/Soroban-CII/soroindex/internal/sync"
	"github.com/Soroban-CII/soroindex/pkg/sepmeta"
)

// Entry is one row of the error catalog.
type Entry struct {
	// Code is the stable identifier written to JSON errors.
	Code string
	// Exit is the process status a failure with this code returns.
	Exit int
	// SentinelName is "package.ErrName" for a sentinel, or "" for the
	// internal fallback that has no sentinel.
	SentinelName string
	// Err is the sentinel value, nil for the fallback.
	Err error
	// Meaning says when the code is returned, in one sentence.
	Meaning string
}

// Exit codes are part of the CLI contract (CLAUDE.md §5.12).
const (
	ExitOK       = 0
	ExitError    = 1
	ExitNotFound = 2
)

// catalog is ordered for the docs page: general input errors first, then
