// Catalog returns every error code. The slice is a copy, so callers cannot
// change the mapping.
func Catalog() []Entry {
	out := make([]Entry, len(catalog))
	copy(out, catalog)
	return out
}

// Markdown renders docs/errors.md. It lives here so the docs page and the
// mapping are generated from the same values; the generator script only
// writes the result.
func Markdown() string {
	var b strings.Builder
	b.WriteString("# CLI error catalog\n\n")
	b.WriteString("Every `sep47idx` failure has a stable code. With `--json` the command writes\n")
	b.WriteString("`{\"error\":{\"code\":\"...\",\"message\":\"...\"}}` to stderr; without it, the same\n")
	b.WriteString("message is printed as `sep47idx <command>: <message>`. Exit status is 0 on\n")
	b.WriteString("success, 1 on error, and 2 when the requested object does not exist.\n\n")
	b.WriteString("This page is generated by `scripts/gen-error-catalog.sh` from\n")
	b.WriteString("`internal/clierr`; do not edit it by hand.\n\n")
	b.WriteString("| Code | Exit | Sentinel | When |\n")
	b.WriteString("| --- | ---: | --- | --- |\n")
	for _, e := range catalog {
		sentinel := "—"
		if e.SentinelName != "" {
			sentinel = "`" + e.SentinelName + "`"
		}
		fmt.Fprintf(&b, "| `%s` | %d | %s | %s |\n", e.Code, e.Exit, sentinel, e.Meaning)
	}
	return b.String()
}

// Error is an error carrying an explicit catalog code. New refuses a code
// that is not in the catalog, because an uncatalogued code would document
// itself only in prose.
type Error struct {
	Code    string
	Message string
}

func (e *Error) Error() string { return e.Message }

// Newf returns a tagged error with the given code. The code must exist in
// the catalog; an unknown code becomes internal so a typo cannot invent a
// documented code.
func Newf(code, format string, args ...any) error {
	if _, ok := lookupCode(code); !ok {
		code = "internal"
	}
	return &Error{Code: code, Message: fmt.Sprintf(format, args...)}
}

func lookupCode(code string) (int, bool) {
	for _, e := range catalog {
		if e.Code == code {
			return e.Exit, true
		}
	}
	return 0, false
}

// Classify returns the stable code and exit status for err. A tagged error
// wins over its wrapped cause, sentinels are matched with errors.Is, and
// anything else is internal.
func Classify(err error) (code string, exit int) {
	var tagged *Error
	if errors.As(err, &tagged) {
		if x, ok := lookupCode(tagged.Code); ok {
			return tagged.Code, x
		}
		return "internal", ExitError
	}
	for _, e := range catalog {
		if e.Err != nil && errors.Is(err, e.Err) {
			return e.Code, e.Exit
		}
	}
	return "internal", ExitError
}
